// Writes src/core/realityloop/site-check-script.ts: the script the sandbox runs
// for `farbaek check-site` (ADR 0054), built from checkSite's own source in
// site-check.ts so the check people approve and the check that runs can't
// drift apart. Node 24 strips the types. Run it after changing checkSite:
//
//   node scripts/site-check-script.mjs           write the file
//   node scripts/site-check-script.mjs --check   exit 1 if the file is out of date
//
// The generated file is plain JavaScript in a string, so no bundler or
// minifier ever changes what the sandbox runs.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { checkSite } from "../src/core/realityloop/site-check.ts";

const OUT = fileURLToPath(new URL("../src/core/realityloop/site-check-script.ts", import.meta.url));

// Unix line endings, so a Windows checkout (CRLF) and the Linux server generate the same script.
const source = checkSite.toString().replace(/\r\n/g, "\n");

const script = `// Farbaek's site check (ADR 0054). Written by Farbaek for this check run; not part of the project.
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
const checkSite = ${source};
const paths = [];
const walk = (dir, prefix) => {
  for (const name of readdirSync(dir)) {
    if (name.startsWith(".") || name === "node_modules") continue;
    const full = join(dir, name);
    const rel = prefix ? prefix + "/" + name : name;
    if (statSync(full).isDirectory()) walk(full, rel);
    else paths.push(rel);
  }
};
walk(process.cwd(), "");
const TEXT = /\\.(html?|css|svg|js|mjs|json|txt|md|xml)$/i;
const read = (p) => (TEXT.test(p) ? readFileSync(join(process.cwd(), p), "utf8") : null);
const result = checkSite(paths, read);
for (const p of result.problems) console.log("- " + p);
console.log(result.problems.length === 0 ? "Checked " + result.pages + " pages: nothing wrong." : "Checked " + result.pages + " pages: " + result.problems.length + " to fix.");
process.exit(result.problems.length === 0 ? 0 : 1);
`;

const file = `// Generated by scripts/site-check-script.mjs from checkSite in site-check.ts (ADR 0054). Don't edit by hand.
/** The script the sandbox runs for \`farbaek check-site\`. */
export const SITE_CHECK_SCRIPT = ${JSON.stringify(script)};
`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8").replace(/\r\n/g, "\n");
  } catch {
    // Missing counts as out of date.
  }
  if (current !== file) {
    console.error("src/core/realityloop/site-check-script.ts is out of date: run node scripts/site-check-script.mjs");
    process.exit(1);
  }
  console.log("site-check-script.ts is up to date.");
} else {
  writeFileSync(OUT, file);
  console.log("Wrote src/core/realityloop/site-check-script.ts.");
}
